const today = new Date().toISOString().slice(0,10);
const isReal = x => x && Object.keys(x).length > 0;
const leads = $('Fetch Recent Leads').all().map(i => i.json).filter(isReal);
const invoices = $('Fetch Recent Invoices').all().map(i => i.json).filter(isReal);
const reminders = $('Fetch Payment Reminders').all().map(i => i.json).filter(isReal);
const quotes = $('Fetch Recent Quotes').all().map(i => i.json).filter(isReal);
const todayOnly = row => String(row.created_at || '').slice(0,10) === today;
const todayLeads = leads.filter(todayOnly);
const todayInvoices = invoices.filter(todayOnly);
const todayQuotes = quotes.filter(todayOnly);
const todayReminders = reminders.filter(todayOnly);
const sales = todayInvoices.reduce((s, x) => s + Number(x.total || 0), 0);
const paidSales = todayInvoices.filter(x => String(x.payment_status || x.status || '').toLowerCase().includes('paid')).reduce((s, x) => s + Number(x.total || 0), 0);
const unpaid = invoices.filter(x => !String(x.payment_status || x.status || '').toLowerCase().includes('paid')).reduce((s, x) => s + Number(x.total || x.amount_due || 0), 0);
const hotLeads = todayLeads.filter(x => Number(x.lead_score || 0) >= 75 || String(x.temperature || '').toLowerCase() === 'hot');
const handoffs = todayLeads.filter(x => x.human_required === true || String(x.status || '').includes('handoff'));
const pendingQuotes = quotes.filter(x => !['accepted','rejected','expired','cancelled'].includes(String(x.status || '').toLowerCase()));
const approvalReminders = todayReminders.filter(x => String(x.status || '').includes('approval'));
const ownerPhone = [...todayLeads, ...todayInvoices, ...todayQuotes, ...todayReminders, ...leads, ...invoices, ...quotes, ...reminders].find(x => x.owner_phone)?.owner_phone || '923000000000';
const phoneNumberId = [...todayLeads, ...todayInvoices, ...todayQuotes, ...todayReminders, ...leads, ...invoices, ...quotes, ...reminders].find(x => x.phone_number_id)?.phone_number_id || 'YOUR_PHONE_NUMBER_ID';
const businessId = [...todayLeads, ...todayInvoices, ...todayQuotes, ...todayReminders, ...leads, ...invoices, ...quotes, ...reminders].find(x => x.business_id)?.business_id || 'default';
return [{ json: {
  business_id: businessId,
  brief_date: today,
  period: 'evening',
  owner_phone: String(ownerPhone).replace(/\D/g, ''),
  phone_number_id: phoneNumberId,
  metrics: {
    leads_today: todayLeads.length,
    hot_leads_today: hotLeads.length,
    handoffs_today: handoffs.length,
    invoices_today: todayInvoices.length,
    sales_today: sales,
    paid_sales_today: paidSales,
    estimated_unpaid_total: unpaid,
    quotes_today: todayQuotes.length,
    pending_quotes: pendingQuotes.length,
    approval_reminders_today: approvalReminders.length
  },
  source_samples: {
    hot_leads: hotLeads.slice(0,5),
    handoffs: handoffs.slice(0,5),
    pending_quotes: pendingQuotes.slice(0,5),
    approval_reminders: approvalReminders.slice(0,5)
  },
  created_at: new Date().toISOString()
}}];

const source = $('Aggregate Business Metrics').item.json;
let ai = {};
try { ai = JSON.parse($input.first().json.choices?.[0]?.message?.content || '{}'); } catch (e) { ai = {}; }
const actions = Array.isArray(ai.top_actions) ? ai.top_actions.slice(0,3) : [];
const m = source.metrics || {};
const actionText = actions.length ? actions.map((a, i) => `${i+1}. ${a.title} — ${a.why}`).join('\n') : 'No urgent action detected.';
const message = `Daily Brief — ${source.brief_date}\n\nSales today: Rs ${m.sales_today || 0}\nPaid sales: Rs ${m.paid_sales_today || 0}\nEstimated unpaid: Rs ${m.estimated_unpaid_total || 0}\nHot leads: ${m.hot_leads_today || 0}\nPending quotes: ${m.pending_quotes || 0}\nPayment approvals: ${m.approval_reminders_today || 0}\n\nRisk: ${ai.risk_level || 'low'}\n\nTop actions:\n${actionText}`;
return [{ json: {
  business_id: source.business_id,
  brief_date: source.brief_date,
  period: source.period,
  owner_phone: source.owner_phone,
  phone_number_id: source.phone_number_id,
  headline: ai.headline || 'Daily business brief',
  risk_level: ai.risk_level || 'low',
  metrics_json: JSON.stringify(source.metrics),
  recommendations_json: JSON.stringify(actions),
  message,
  created_at: new Date().toISOString()
}}];
